        clBlue   := '004488';
        clYellow := 'FFFF00';
        clRed    := 'FF0000';
        clBlack  := '333333';

        K := 0.6;

        D1 := K * 0.951;
        D2 := K * 0.82;
        D3 := K * 1.05;
        D4 := K * 1.01;
        D5 := K * 0.90;

        DCut1 := D2 - K * 0.2;
        DCut2 := D1 - K * 0.2;

        R1 := K  * 0.42;
        H1 := D1 * 1.10;

        R2 := K  * 0.20;
        H2 := D3 * 1.02;

        Ang := Arccos(4 / sqrt(17));

        N := 40;

        procedure CalcCylinder( R, H, D);
        begin
            for i := 0 to N - 1 do begin
                x[i] := R * cos(2*Pi / N * i);
                y[i] := R * sin(2*Pi / N * i);
            end;
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

